pou.interface:
{implicit on}
FUNCTION __HelpConvertStringBase64 : LWORD
VAR_INPUT
	pstr : POINTER TO BYTE;
	nBase : INT;
END_VAR
VAR
	nNext : INT;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
WHILE(pstr[0] <> 0) DO
	IF (pstr[0] = 16#5f) THEN (*'_'*)
		pstr := pstr + 1;
	ELSE
		IF ((nBase = 2 AND pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#31 (*'1'*)) 
			OR (nBase = 8 AND pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#37 (*'7'*))
			OR (nBase = 10 AND pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#39 (*'9'*))
			OR (nBase = 16 AND pstr[0] >= 16#30 (*'0'*) AND pstr[0] <= 16#39 (*'9'*)))
		THEN
			nNext := pstr[0] - 16#30;
		ELSIF (nBase = 16 AND pstr[0] >= 16#41 (*'A'*) AND pstr[0] <= 16#46 (*'F'*)) THEN
			nNext := pstr[0] - 16#41 + 10;
		ELSIF (nBase = 16 AND pstr[0] >= 16#61 (*'a'*) AND pstr[0] <= 16#66 (*'f'*)) THEN
			{IF COMPILERVERSION(>=, '3.4.0.0')}					
				nNext := pstr[0] - 16#61 + 10;
			{ELSE}
				nNext := pstr[0] - 16#46 + 10;
			{END_IF}					
		ELSE
			EXIT;
		END_IF
		__HelpConvertStringBase64 := LINT_TO_LWORD(LWORD_TO_LINT(__HelpConvertStringBase64) * nBase + nNext);
		pstr := pstr + 1;
	END_IF
END_WHILE
IF (pstr[0] <> 0 AND pstr[0] <> 16#2e(*'.'*)) THEN
	__HelpConvertStringBase64 := 0; 
END_IF
{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpLConvert : BOOL
VAR_INPUT
	in : ULINT;
	ppstr : POINTER TO POINTER TO BYTE;
	nWidth : DINT;
END_VAR
VAR
	ulDiv : ULINT := 10000000000000000000;
	bFirst : BOOL;
	pstr : POINTER TO BYTE := ppstr^;
	nDigits : DINT := 20;
	ulDig : ULINT;
	count: UDINT;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
WHILE (ulDiv > 0) DO
	ulDig := in / ulDiv;
	IF ((NOT bFirst AND ulDig <> 0) OR (nDigits <= nWidth)) THEN
		bFirst := TRUE;
	END_IF
	IF (bFirst) THEN
		pstr[0] := ULINT_TO_BYTE(ulDig + 16#30); (*'0'*)
		pstr := pstr + 1; 
		in := in MOD ulDiv;
		count := count + 1;
	END_IF
	ulDiv := ulDiv / 10;
	nDigits := nDigits-1;
END_WHILE

pstr[0] := 0; (*'\0'*)
ppstr^ := pstr;

{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertLTimeUnits : ULINT
VAR_INPUT
	ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
	pstr : POINTER TO BYTE := ppstr^;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}

{IF COMPILERVERSION(>=, '3.5.21.0')}

	CASE (pstr[0]) OF
		16#64,16#44: (*'d','D'*)
			__HelpConvertLTimeUnits := 86400000000000;		
		16#68,16#48: (*'h','H'*)
			__HelpConvertLTimeUnits := 3600000000000;
		16#73,16#53: (*'s','S'*)
			__HelpConvertLTimeUnits  := 1000000000;
		16#6D,16#4D: (*'m','M'*)
			IF (pstr[1] = 16#73 OR pstr[1] = 16#53) THEN
				pstr := pstr+1;
				__HelpConvertLTimeUnits  := 1000000;
			ELSE
				__HelpConvertLTimeUnits  := 60000000000;
			END_IF
		16#75,16#55: (*'us','US'*)
			IF (pstr[1] = 16#73 OR pstr[1] = 16#53) THEN
				pstr := pstr+1;
				__HelpConvertLTimeUnits  := 1000;
			ELSE
				__HelpConvertLTimeUnits  := 0;
			END_IF				
		16#6E,16#4E: (*'ns','NS'*)
			IF (pstr[1] = 16#73 OR pstr[1] = 16#53) THEN
				pstr := pstr+1;
				__HelpConvertLTimeUnits  := 1;
			ELSE
				__HelpConvertLTimeUnits  := 0;
			END_IF				
		ELSE 
			__HelpConvertLTimeUnits  :=  0;

		IF (pstr[0] = 16#00) THEN
				RETURN;
		END_IF       
	END_CASE		

{ELSE}

	CASE (pstr[0]) OF
		16#64: (*'d'*)
			__HelpConvertLTimeUnits := 86400000000000;		
		16#68: (*'h'*)
			__HelpConvertLTimeUnits := 3600000000000;
		16#73: (*'s'*)
			__HelpConvertLTimeUnits  := 1000000000;
		16#6D: (*'m'*)
			IF (pstr[1] = 16#73) THEN
				pstr := pstr+1;
				__HelpConvertLTimeUnits  := 1000000;
			ELSE
				__HelpConvertLTimeUnits  := 60000000000;
			END_IF
		16#75: (*'us'*)
			IF (pstr[1] = 16#73) THEN
				pstr := pstr+1;
				__HelpConvertLTimeUnits  := 1000;
			ELSE
				__HelpConvertLTimeUnits  := 0;
			END_IF				
		16#6E: (*'ns'*)
			IF (pstr[1] = 16#73) THEN
				pstr := pstr+1;
				__HelpConvertLTimeUnits  := 1;
			ELSE
				__HelpConvertLTimeUnits  := 0;
			END_IF				
		ELSE 
			__HelpConvertLTimeUnits  :=  0;
		  {IF COMPILERVERSION(>=, '3.5.2.0')}
	IF (pstr[0] = 16#00) THEN
			RETURN;
	END_IF       
		  {END_IF}        
	END_CASE		

{END_IF}

pstr := pstr+1;
ppstr^ := pstr;
{implicit off}

pou.interface:
{implicit on}
FUNCTION __HelpConvertLTimeWithUnit : BOOL
VAR_INPUT
	in : ULINT;
	ppstr : POINTER TO POINTER TO BYTE;
END_VAR
VAR
	lwDay : ULINT;
	lwHour : ULINT;
	lwMinute : ULINT;
	lwSecond : ULINT;
	lwMilliSecond : ULINT;
	lwMicroSecond : ULINT;
	lwNanoSecond : ULINT;
	pstr : POINTER TO BYTE := ppstr^;
END_VAR
{implicit off}

pou.body:

{implicit on}
{nobp}
{noflow}
pstr[0] := 16#4C; (*'L'*)
pstr[1] := 16#54; (*'T'*)
pstr[2] := 16#49; (*'I'*)
pstr[3] := 16#4D; (*'M'*)
pstr[4] := 16#45; (*'E'*)
pstr[5] := 16#23; (*'#'*)
pstr := pstr + 6;

IF (in = 0) THEN
	pstr[0] := 16#30; (*'0'*)
	pstr[1] := 16#6E; (*'n'*)
	pstr[2] := 16#73; (*'s'*)
	pstr[3] := 16#0;  (*'\0'*)
	pstr := pstr + 3;
ELSE
	lwDay := in / 86400000000000;
	IF (lwDay <> 0) THEN
		__HelpLConvert(lwDay,ADR(pstr), 1);
		pstr[0] := 16#64; (*'d'*)
		pstr := pstr + 1;
		in := in MOD 86400000000000;
	END_IF

	lwHour := in / 3600000000000;
	IF (lwHour <> 0) THEN
		__HelpLConvert(lwHour,ADR(pstr), 1);
		pstr[0] := 16#68; (*'h'*)
		pstr := pstr + 1;
		in := in MOD 3600000000000;
	END_IF

	lwMinute := in / 60000000000;
	IF (lwMinute <> 0) THEN
		__HelpLConvert(lwMinute,ADR(pstr), 1);
		pstr[0] := 16#6D; (*'m'*)
		pstr := pstr + 1;
		in := in MOD 60000000000;
	END_IF

	lwSecond := in / 1000000000;
	IF (lwSecond <> 0) THEN
		__HelpLConvert(lwSecond,ADR(pstr), 1);
		pstr[0] := 16#73; (*'s'*)
		pstr := pstr + 1;
		in := in MOD 1000000000;
	END_IF

	lwMilliSecond := in / 1000000;
	IF (lwMilliSecond <> 0) THEN
		__HelpLConvert(lwMilliSecond,ADR(pstr), 1);
		pstr[0] := 16#6D; (*'m'*)
		pstr[1] := 16#73; (*'s'*)
		pstr := pstr + 2;
		in := in MOD 1000000;
	END_IF

	lwMicroSecond := in / 1000;
	IF (lwMicroSecond <> 0) THEN
		__HelpLConvert(lwMicroSecond,ADR(pstr), 1);
		pstr[0] := 16#75; (*'u'*)
		pstr[1] := 16#73; (*'s'*)
		pstr := pstr + 2;
		in := in MOD 1000;
	END_IF

	IF (in <> 0) THEN
		__HelpLConvert(in,ADR(pstr), 1);
		pstr[0] := 16#6E; (*'n'*)
		pstr[1] := 16#73; (*'s'*)
		pstr := pstr + 2;			
	END_IF

	pstr[0] := 0; (*'\0'*)
END_IF

ppstr^ := pstr;	
{implicit off}

pou.interface:
{implicit on}
FUNCTION any64__to__string : STRING(255)
VAR_INPUT
in: LWORD;
dwType: DWORD;
END_VAR
VAR
dintHigh: DINT;
udintLow: UDINT;
udintHigh: UDINT;
pstr: POINTER TO BYTE;
ulDiv: LWORD := 10000000000000000000;
ulDig: LWORD;
bFirst: BOOL;
nDigits: INT := 20;
nWidth: INT := 1;
count: INT := 0;

{IF COMPILERVERSION(>=, '3.5.16.0')}
  lwTOD: ULINT;
  lwDATE: ULINT;
{END_IF}

END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
		pstr := ADR(any64__to__string);

          IF (dwType = __TypeClass.TYPE_LDATE) THEN
	          __ConvertLDate_TO_STRING(in, pstr);
	  		  RETURN;
          END_IF
          IF (dwType = __TypeClass.TYPE_LTIMEOFDAY) THEN
	          pstr[0] := 16#4C; (*'L'*)
	          pstr[1] := 16#54; (*'T'*)
	          pstr[2] := 16#4F; (*'O'*)
	          pstr[3] := 16#44; (*'D'*)
	          pstr[4] := 16#23; (*'#'*)
	          pstr := pstr + 5;
	          __HelpConvertLTime(in, ADR(pstr));
	          RETURN;
          END_IF
          IF (dwType = __TypeClass.TYPE_LDATEANDTIME) THEN
	          __ConvertLDateAndTime_TO_STRING(in, pstr);
	          RETURN;
          END_IF

		IF (dwType = __TypeClass.TYPE_LTIME) THEN
			__HelpConvertLTimeWithUnit(in,ADR(pstr));
			RETURN;
		END_IF		
		IF (dwType = __TypeClass.TYPE_LINT	AND in > ULINT#16#7FFFFFFFFFFFFFFF) THEN
			(* Sign of result *)
			in := LINT_TO_LWORD(-(LWORD_TO_LINT(in)));
			pstr[0] := BYTE#16#2d; (*'-'*)
			pstr[1] := 0; (*'\0'*)
			pstr := pstr + 1;
		ELSE
			pstr[0] := 0; (*'\0'*)
		END_IF
		WHILE (ulDiv > 0) DO
			ulDig := in / ulDiv;
			IF ((NOT bFirst AND ulDig <> 0) OR (nDigits <= nWidth)) THEN
				bFirst := TRUE;
			END_IF
			IF (bFirst) THEN
				pstr[0] := LWORD_TO_BYTE(ulDig + 16#30); (*'0'*)
				pstr := pstr + 1; 
				in := in MOD ulDiv;
				count := count + 1;
			END_IF
			ulDiv := ulDiv / ULINT#10;
			nDigits := nDigits-1;
		END_WHILE
		pstr[0] := 0; (*'\0'*)
		{implicit off}

pou.interface:
{implicit on}
FUNCTION string__to__any64 : LWORD
VAR_INPUT
in: STRING(255);
dwType: DWORD;
END_VAR
VAR
pstr : POINTER TO STRING := ADR(in);
strHelp : STRING;
ulHelpLdt: ULINT;
pstrHelp : POINTER TO BYTE;
END_VAR
{implicit off}

pou.body:

		{implicit on}
		{nobp}
		{noflow}
		__SkipWhiteSpace(ADR(pstr));

	IF (dwType = __SYSTEM.TYPE_CLASS.TYPE_LDATE) THEN
		__ConvertSTRING_TO_LDATE(pstr, pout := ADR(string__to__any64));
		RETURN;
	END_IF

	IF (dwType = __SYSTEM.TYPE_CLASS.TYPE_LTIMEOFDAY) THEN
		IF (__LEFT(pstr^, 5) <> 'ltod#') AND (__LEFT(pstr^, 5) <> 'LTOD#') 
			AND (__LEFT(pstr^, 13) <> 'LTIME_OF_DAY#')
			AND (__LEFT(pstr^, 13) <> 'ltime_of_day#') THEN
			string__to__any64 := 0;
			RETURN;
		END_IF
		WHILE (pstr^[0] <> 16#23) (*'#'*) DO
			pstr := pstr+1;
		END_WHILE
		pstr := pstr+1;

  		string__to__any64 := __HelpConvertFromLTime(ADR(pstr));
		RETURN; 
	END_IF

	IF (dwType = __SYSTEM.TYPE_CLASS.TYPE_LDATEANDTIME) THEN
		__ConvertSTRING_TO_LDATEANDTIME(pstr, pout := ADR(string__to__any64));
		RETURN;
	END_IF

		IF (dwType = __TypeClass.TYPE_LTIME) THEN
			IF (__LEFT(pstr^, 6) <> 'LTIME#') AND (__LEFT(pstr^, 6) <> 'ltime#') THEN
				string__to__any64 := 0;
				RETURN;
			END_IF
			WHILE (pstr^[0] <> 16#23) (*'#'*) DO
				pstr := pstr+1;
			END_WHILE
			pstr := pstr+1;

			WHILE (pstr^[0] <> 0 (*'\0'*)) DO
				pstrHelp := ADR(strHelp);
				WHILE((pstr^[0] >= 16#30(*'0'*) AND pstr^[0] <= 16#39(*'9'*)) OR pstr^[0] = 16#5f (*'_'*)) DO
					IF (pstr^[0] = 16#5f (*'_'*)) THEN
						pstr := pstr + 1;
					ELSE
						pstrHelp[0] := pstr^[0];
						pstrHelp := pstrHelp+1;
						pstr := pstr+1;
					END_IF
				END_WHILE
				string__to__any64 := string__to__any64  + __HelpConvertString(ADR(strHelp),pstrHelp-ADR(strHelp)) * __HelpConvertLTimeUnits(ADR(pstr));
			END_WHILE
			RETURN;
		END_IF

		IF (dwType = __TypeClass.TYPE_LINT OR dwType = __TypeClass.TYPE_LWORD OR dwType = __TypeClass.TYPE_ULINT)
		THEN
			IF pstr^[0] = 0 (*'\0'*) THEN
				string__to__any64 := 0;
				RETURN;
			END_IF
			IF (__LEFT(pstr^, 3) = '16#') THEN
				string__to__any64 := __HelpConvertStringBase64(pstr + 3,16);
				RETURN;
			ELSIF (__LEFT(pstr^, 2) = '2#')THEN
				string__to__any64 := __HelpConvertStringBase64(pstr + 2,2);
				RETURN;
			ELSIF  (__LEFT(pstr^, 2) = '8#') THEN
				string__to__any64 := __HelpConvertStringBase64(pstr + 2,8);
				RETURN;
			ELSE 
				IF (pstr^[0] = BYTE#16#2d (*'-'*) AND dwType = __TypeClass.TYPE_LINT)
				THEN
					pstr := pstr+1;
					string__to__any64 := LINT_TO_ULINT(- ULINT_TO_LINT(__HelpConvertStringBase64(pstr,10)));
					RETURN;
				ELSE
					IF (pstr^[0] = BYTE#16#2b (*'+'*)) THEN
						pstr := pstr+1;
					END_IF
					string__to__any64 := __HelpConvertStringBase64(pstr,10);
					RETURN;
				END_IF
			END_IF
			string__to__any64 := 0;
			RETURN; 
		END_IF		
		{implicit off}
